import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

function Questionnaire({ onNext }) {
  const navigate = useNavigate();

  const [formData, setFormData] = useState({
    incomeStability: "",
    savingHabit: "",
    majorExpense: "",
    riskLevel: "",
    expenseControl: ""
  });

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleContinue = () => {
    // call onNext ONLY if it exists
    if (typeof onNext === "function") {
      onNext(formData);
    }

    // always move forward
    navigate("/spending-priority");
  };

  return (
    <div style={{ textAlign: "center", color: "white", padding: "40px" }}>
      <h1>Financial Questionnaire</h1>

      <div style={{ marginTop: "20px" }}>
        <p>Income Stability</p>
        <select name="incomeStability" onChange={handleChange}>
          <option value="">Select</option>
          <option>Stable</option>
          <option>Somewhat Stable</option>
          <option>Unstable</option>
        </select>

        <p>Saving Habit</p>
        <select name="savingHabit" onChange={handleChange}>
          <option value="">Select</option>
          <option>Regularly</option>
          <option>Sometimes</option>
          <option>Rarely</option>
        </select>

        <p>Major Expense</p>
        <select name="majorExpense" onChange={handleChange}>
          <option value="">Select</option>
          <option>Food & Groceries</option>
          <option>Bills</option>
          <option>Shopping</option>
        </select>

        <p>Risk Level</p>
        <select name="riskLevel" onChange={handleChange}>
          <option value="">Select</option>
          <option>Low</option>
          <option>Medium</option>
          <option>High</option>
        </select>

        <p>Expense Control</p>
        <select name="expenseControl" onChange={handleChange}>
          <option value="">Select</option>
          <option>Good</option>
          <option>Average</option>
          <option>Poor</option>
        </select>

        <br /><br />

        <button
          onClick={handleContinue}
          style={{
            padding: "12px 30px",
            fontSize: "16px",
            borderRadius: "8px",
            border: "none",
            background: "#ffffff",
            color: "#1e3c72",
            cursor: "pointer"
          }}
        >
          Continue
        </button>
      </div>
    </div>
  );
}

export default Questionnaire;
